INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (1,1,'["Vous êtes titulaire d''un Master en Gestion des entreprises et non d''un diplôme d''architecture : comment compensez-vous cette lacune technique pour piloter des projets architecturaux complexes ?", "Décrivez concrètement votre méthodologie pour coordonner les phases d''un projet architectural, de l''esquisse jusqu''à la réception des travaux.", "Comment gérez-vous les écarts entre le budget initial et les coûts réels d''un projet de construction, notamment dans un contexte de marché public soumis au Code des Marchés Marocains ?", "Sur vos 9 années d''expérience, citez un projet dont vous avez assuré le pilotage complet et précisez votre rôle exact, le budget engagé et les délais respectés ou non.", "Votre formation est orientée gestion d''entreprise : en quoi cela constitue-t-il, selon vous, un atout réel pour un poste de chef de projets architecte dans une agence publique ?", "Avez-vous déjà travaillé sur des projets à maîtrise d''ouvrage publique ? Si oui, quelles contraintes spécifiques avez-vous rencontrées par rapport au secteur privé ?", "Qu''est-ce qui vous motive à rejoindre l''ADER Fès-Meknès plutôt qu''un bureau d''études privé ou un promoteur immobilier ?", "Où vous situez-vous professionnellement dans 5 ans, et en quoi ce poste s''inscrit-il dans cette trajectoire ?", "Que savez-vous des missions et des projets structurants portés par l''ADER Fès-Meknès dans le cadre du développement régional ?", "Le secteur public impose des contraintes réglementaires, des délais administratifs longs et une redevabilité publique : comment vous y adaptez-vous concrètement ?"]','[]','{}','2026-08-27 13:24:57.773679') ON CONFLICT (id) DO NOTHING;